<template><main class="patient-admission-view"><BioNexusTabs v-model="activeTab" :tabs="tabs" aria-label="Fases del ingreso" id-prefix="patient-admission"/><section class="bio-nexus-panel admission-panel"><section v-show="activeTab==='patient'" role="tabpanel"><div v-if="errorMessage" class="bio-nexus-message bio-nexus-message-error">{{errorMessage}}</div><div class="form-grid"><div class="identity-row"><BioNexusFormField class="identity-type" label="Tipo" field-id="pa-code"><select id="pa-code" v-model="draft.verification_code" class="bio-nexus-field"><option v-for="code in patientVerificationCodes" :key="code" :value="code">{{code||'Sin prefijo'}}</option></select></BioNexusFormField><PatientAutocomplete class="identity-document" v-model="draft.document_number" label="Documento" id="pa-document" :error="documentError" :maxlength="10" @blur="documentTouched=true" @select="selectPatient"/><PatientAutocomplete class="identity-name" v-model="draft.name" label="Nombre y apellidos" id="pa-name" :error="nameError" required @blur="nameTouched=true" @select="selectPatient"/></div><BioNexusFormField label="Fecha de nacimiento" field-id="pa-birth"><BioNexusRegionalDateInput id="pa-birth" v-model="draft.birth_date" min="1890-01-01" :max="today" @update:model-value="refreshAge"/></BioNexusFormField><BioNexusFormField label="Edad" field-id="pa-age"><input id="pa-age" v-model.number="draft.age" class="bio-nexus-field calculated-field" type="number" min="0" readonly aria-readonly="true" tabindex="-1" /></BioNexusFormField><BioNexusFormField label="Unidad" field-id="pa-unit"><input id="pa-unit" :value="ageUnitLabel" class="bio-nexus-field calculated-field" type="text" readonly aria-readonly="true" tabindex="-1" /></BioNexusFormField><BioNexusFormField label="Sexo" field-id="pa-sex"><select id="pa-sex" v-model="draft.sex" class="bio-nexus-field"><option v-for="item in patientSexOptions" :key="String(item.value)" :value="item.value">{{item.label}}</option></select></BioNexusFormField><BioNexusFormField label="Muestra" field-id="pa-sample"><select id="pa-sample" v-model="draft.sample" class="bio-nexus-field"><option>Tomada aquí</option><option>Referida</option></select></BioNexusFormField><BioNexusFormField label="Tipo de muestra" field-id="pa-sample-type"><select id="pa-sample-type" v-model="draft.sample_type" class="bio-nexus-field"><option value="">Seleccione</option><option v-for="item in sampleTypes" :key="item.id||item.description" :value="item.description">{{item.description}}</option></select></BioNexusFormField><BioNexusFormField label="Teléfono" field-id="pa-phone"><input id="pa-phone" v-model.trim="draft.phone" class="bio-nexus-field" maxlength="20"/></BioNexusFormField><BioNexusFormField label="Referido por" field-id="pa-client"><BioNexusSearchableSelect id="pa-client" v-model="draft.client_id" :options="clients" value-key="id" label-key="business_name" search-placeholder="Buscar referido..." empty-text="Sin referidos coincidentes" /></BioNexusFormField><BioNexusFormField label="Sugerido por" field-id="pa-suggested"><input id="pa-suggested" v-model.trim="draft.suggested" class="bio-nexus-field" maxlength="60"/></BioNexusFormField><label class="check"><input v-model="draft.urgent" type="checkbox"/>Ingreso urgente</label><label class="check"><input v-model="draft.email_sent" type="checkbox"/>Enviar resultados por correo</label><BioNexusFormField v-if="draft.email_sent" label="Correo" field-id="pa-email" :error="emailError"><input id="pa-email" v-model.trim="draft.email" class="bio-nexus-field" type="email"/></BioNexusFormField><BioNexusFormField class="span-2" label="Domicilio" field-id="pa-address"><textarea id="pa-address" v-model.trim="draft.address" class="bio-nexus-field textarea" maxlength="250"></textarea></BioNexusFormField><BioNexusFormField label="Observación" field-id="pa-observation"><textarea id="pa-observation" v-model.trim="draft.observation" class="bio-nexus-field textarea" maxlength="100"></textarea></BioNexusFormField></div></section><section v-if="activeTab==='exams'" role="tabpanel"><PatientAdmissionExamsStep v-model="selectedExams" v-model:tariff-id="draft.tariff_id" :client-id="Number(draft.client_id)||1" :tariffs="tariffs" @summary-change="updateExamSummary" /></section><section v-show="activeTab==='payment'" class="phase-placeholder"><strong>Pago y cierre</strong><p>Las formas de pago y el cierre se integrarán aquí.</p></section><section v-show="activeTab==='summary'" class="phase-placeholder"><strong>Resumen</strong><p>Revisión final antes de registrar.</p></section><footer><button class="bio-nexus-action bio-nexus-action-secondary" :disabled="!dirty" @click="resetDraft"><BioNexusActionIcon action="cancel"/>Descartar</button></footer></section></main></template><script setup>
import PatientAdmissionExamsStep from "@/components/patients/PatientAdmissionExamsStep.vue";import BioNexusSearchableSelect from "@/components/ui/BioNexusSearchableSelect.vue";import{computed,onMounted,reactive,ref,watch}from"vue";import BioNexusTabs from"@/components/ui/BioNexusTabs.vue";import BioNexusFormField from"@/components/ui/BioNexusFormField.vue";import BioNexusActionIcon from"@/components/ui/BioNexusActionIcon.vue";import BioNexusRegionalDateInput from"@/components/regional/BioNexusRegionalDateInput.vue";import PatientAutocomplete from"@/components/patients/PatientAutocomplete.vue";import{calculatePatientAge,createPatientAdmissionDraft,normalizePatientAdmissionDraft,patientAgeUnits,patientSexOptions,patientVerificationCodes}from"@/models/patientAdmission";import{getActiveAdmissionTariffs,getAdmissionClients,getAdmissionSampleTypes,patientAdmissionError}from"@/services/patientAdmissionService";const tabs=[{key:"patient",label:"Paciente"},{key:"exams",label:"Exámenes"},{key:"payment",label:"Pago y cierre"},{key:"summary",label:"Resumen"}],activeTab=ref("patient"),draft=reactive(createPatientAdmissionDraft()),clients=ref([]),tariffs=ref([]),sampleTypes=ref([]),errorMessage=ref(""),original=ref(""),nameTouched=ref(false),documentTouched=ref(false);const selectedExams=ref([]),examSummary=ref({subtotal:0,taxTotal:0,total:0});function updateExamSummary(value){examSummary.value=value||{subtotal:0,taxTotal:0,total:0}}watch(()=>draft.client_id,(current,previous)=>{if(Number(current)!==Number(previous))draft.tariff_id=null})
const today=new Date().toISOString().slice(0,10),signature=computed(()=>JSON.stringify(normalizePatientAdmissionDraft(draft))),dirty=computed(()=>signature.value!==original.value),ageUnitLabel=computed(()=>patientAgeUnits.find((item)=>item.value===draft.month_year)?.label||""),nameError=computed(()=>nameTouched.value&&!draft.name.trim()?"El nombre es obligatorio.":""),documentError=computed(()=>documentTouched.value&&draft.document_number&&String(draft.document_number).replace(/D/g,'').length<4?"Documento inválido.":""),emailError=computed(()=>draft.email_sent&&draft.email&&!/^[^s@]+@[^s@]+.[^s@]+$/.test(draft.email)?"Correo inválido.":"");function mark(){original.value=signature.value}function refreshAge(){const value=calculatePatientAge(draft.birth_date);draft.age=value.age;draft.month_year=value.unit}function selectPatient(row){const selectedClientId=Number(draft.client_id)||1;Object.assign(draft,normalizePatientAdmissionDraft({...row,birth_date:String(row.birth_date||'').slice(0,10)}));draft.client_id=selectedClientId;refreshAge();mark()}function resetDraft(){selectedExams.value=[];examSummary.value={subtotal:0,taxTotal:0,total:0};Object.assign(draft,createPatientAdmissionDraft());nameTouched.value=false;documentTouched.value=false;mark();activeTab.value="patient"}onMounted(async()=>{try{[clients.value,tariffs.value,sampleTypes.value]=await Promise.all([getAdmissionClients(),getActiveAdmissionTariffs(),getAdmissionSampleTypes()]);clients.value=[...clients.value.map((client)=>({...client,id:Number(client.id),business_name:String(client.business_name||"").trim()})).filter((client)=>client.id!==1),{id:1,business_name:"Ambulatorio",discount:0,credit:false,Print_invoice:true,hide_client:false,reserved:true}].sort((left,right)=>left.id===1?-1:right.id===1?1:left.business_name.localeCompare(right.business_name,"es",{sensitivity:"base"}));draft.client_id=1;draft.tariff_id=Number(tariffs.value.find((tariff)=>tariff.isDefault)?.id)||null;if(clients.value.some((client)=>Number(client.id)===1))draft.client_id=1}catch(error){errorMessage.value=patientAdmissionError(error)}finally{mark()}});</script><style scoped>.patient-admission-view{display:grid;gap:var(--bio-nexus-space-3);min-width:0}.admission-panel{display:grid;gap:var(--bio-nexus-space-3);padding:var(--bio-nexus-space-4)}.form-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--bio-nexus-space-3);align-items:end}.span-2{grid-column:span 2}.identity-row{display:grid;grid-column:1/-1;grid-template-columns:120px minmax(180px,240px) minmax(320px,1fr);gap:var(--bio-nexus-space-3);align-items:end;margin-bottom:-18px}.identity-type,.identity-document,.identity-name{position:relative;min-width:0;padding-bottom:18px}.identity-row :deep(.bio-nexus-form-field-error){position:absolute;left:0;right:0;bottom:0;min-height:18px;margin:0;padding:2px 8px 0;overflow:hidden;font-size:12px;line-height:16px;white-space:nowrap;text-overflow:ellipsis}.calculated-field{background:var(--bio-nexus-color-surface-soft);color:var(--bio-nexus-color-text-secondary);cursor:not-allowed}.check{display:flex;align-items:center;gap:8px;min-height:var(--bio-nexus-control-height)}.textarea{min-height:76px;resize:vertical}.phase-placeholder{min-height:260px;padding:var(--bio-nexus-space-5);border:1px dashed var(--bio-nexus-color-border-strong);border-radius:var(--bio-nexus-radius-md);background:var(--bio-nexus-color-surface-soft)}footer{display:flex;justify-content:flex-end;padding-top:var(--bio-nexus-space-3);border-top:1px solid var(--bio-nexus-color-border)}@media(max-width:1050px){.form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:760px){.identity-row{grid-template-columns:110px minmax(0,1fr)}.identity-name{grid-column:1/-1}}@media(max-width:620px){.form-grid,.identity-row{grid-template-columns:1fr}.span-2,.identity-row,.identity-name{grid-column:auto}}</style>